func BenchmarkEncodeDecodeEdge(b *testing.B) {
	seed := v14.Edge{
		Key:    "test_1",
		Source: v14.Handle{Node: "test_3", Param: "test_4"},
		Target: v14.Handle{Node: "test_6", Param: "test_7"},
		Config: v14.EdgeConfig{Variant: v14.PipeEdgeConfig{SegmentedEdgeConfig: fullyPopulatedSegmentedEdgeConfig}},
	}
	w := orc.NewWriter(0)
	r := orc.NewReader(nil)
	for b.Loop() {
		w.Reset()
		if err := seed.EncodeOrc(w); err != nil {
			b.Fatal(err)
		}
		var decoded v14.Edge
		r.ResetBytes(w.Bytes())
		if err := decoded.DecodeOrc(r); err != nil {
			b.Fatal(err)
		}
	}
}

