func FuzzDecodeEdge(f *testing.F) {
	{
		seed := v14.Edge{
			Key:    "test_1",
			Source: v14.Handle{Node: "test_3", Param: "test_4"},
			Target: v14.Handle{Node: "test_6", Param: "test_7"},
			Config: v14.EdgeConfig{Variant: v14.PipeEdgeConfig{SegmentedEdgeConfig: fullyPopulatedSegmentedEdgeConfig}},
		}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	{
		seed := v14.Edge{
			Key:    "",
			Source: v14.Handle{Node: "", Param: ""},
			Target: v14.Handle{Node: "", Param: ""},
			Config: v14.EdgeConfig{Variant: v14.PipeEdgeConfig{
				SegmentedEdgeConfig: v14.SegmentedEdgeConfig{
					StrokeColor: nil,
					Segments:    []v14.Segment{},
					StrokeWidth: 0,
				},
			}},
		}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	f.Fuzz(func(t *testing.T, data []byte) {
		var decoded v14.Edge
		r := orc.NewReader(nil)
		r.ResetBytes(data)
		if err := decoded.DecodeOrc(r); err != nil {
			return
		}
		w1 := orc.NewWriter(len(data))
		if err := decoded.EncodeOrc(w1); err != nil {
			t.Fatalf("encode after successful decode failed: %v", err)
		}
		var redecoded v14.Edge
		r.ResetBytes(w1.Bytes())
		if err := redecoded.DecodeOrc(r); err != nil {
			t.Fatalf("re-decode failed: %v", err)
		}
		if !testutil.DeepEqual(decoded, redecoded) {
			t.Fatal("round-trip mismatch: decoded value changed after an encode/decode cycle")
		}
	})
}

